'use strict';
// MiniLedger 基准测量 harness：启动被测服务、施加固定的读写混合负载、输出单行 JSON 指标。
// 本文件是测量契约的一部分，实验期间不可修改（见 spec.yaml scope.immutable）。
// 负载形态：先 seed 400 条 + 500 次 GET 预热，再 5 轮 × (800 POST + 3200 GET) 计量，
// 轮间做一次校验 GET 防止缓存漏更新等退化行为获得好分数。

const http = require('http');
const { spawn } = require('child_process');
const path = require('path');

const CONC = 16;
const SEED = 400;
const WARMUP_GETS = 500;
const ROUNDS = 5;
const POSTS_PER_ROUND = 800;
const GETS_PER_ROUND = 3200;
const MEASURED_POSTS = ROUNDS * POSTS_PER_ROUND;
const MEASURED_GETS = ROUNDS * GETS_PER_ROUND;
const MEASURED_TOTAL = MEASURED_POSTS + MEASURED_GETS;
const BOOT_TIMEOUT_MS = 10000;

let child = null;
let port = 0;
let finished = false;
const agent = new http.Agent({ keepAlive: true, maxSockets: CONC });

function emit(obj) {
  process.stdout.write(JSON.stringify(obj) + '\n');
}

function fail(reason) {
  if (finished) return;
  finished = true;
  if (child) { try { child.kill('SIGKILL'); } catch (_) { /* 已退出 */ } }
  emit({
    boot_ok: 0, post_ok: 0, get_ok: 0, round_len_ok: 0, final_field_ok: 0,
    rps: 0, p95_ms: 0, p50_ms: 0, p99_ms: 0, mean_ms: 0, post_rps: 0, get_rps: 0,
    boot_ms: 0, entries_final: 0, harness_error: String(reason),
  });
  process.exit(0);
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// 单次独立请求（不走 keep-alive 池），用于就绪探测与轮间校验，避免干扰计量连接
function requestOnce() {
  return new Promise((resolve, reject) => {
    const r = http.request({ host: '127.0.0.1', port, path: '/entries', method: 'GET', agent: false }, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => resolve({ status: res.statusCode, body: Buffer.concat(chunks).toString('utf8') }));
    });
    r.setTimeout(2000, () => r.destroy(new Error('probe_timeout')));
    r.on('error', reject);
    r.end();
  });
}

function request(method, bodyStr) {
  return new Promise((resolve, reject) => {
    const payload = bodyStr === undefined ? null : Buffer.from(bodyStr);
    const headers = {};
    if (payload) {
      headers['content-type'] = 'application/json';
      headers['content-length'] = payload.length;
    }
    const r = http.request({ host: '127.0.0.1', port, path: '/entries', method, agent, headers }, (res) => {
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => resolve({ status: res.statusCode, body: Buffer.concat(chunks) }));
    });
    r.on('error', reject);
    if (payload) r.end(payload); else r.end();
  });
}

// 并发计量池：CONC 个 worker 依序拉取任务，逐请求记录延迟。
// GET 成功判定刻意保持轻量（状态码 + 数组首尾字节），避免 client 侧 JSON.parse
// 大响应把自己 CPU 打满，反而成为被测服务的瓶颈。
async function runPool(tasks) {
  const stats = { lat: [], postOk: 0, getOk: 0 };
  let idx = 0;
  async function worker() {
    for (;;) {
      const i = idx++;
      if (i >= tasks.length) return;
      const t = tasks[i];
      const s = process.hrtime.bigint();
      const res = await request(t.method, t.body);
      stats.lat.push(Number(process.hrtime.bigint() - s) / 1e6);
      if (t.method === 'POST') {
        if (res.status === 200 && res.body.toString('utf8') === 'ok') stats.postOk++;
      } else if (
        res.status === 200 &&
        res.body.length >= 2 &&
        res.body[0] === 0x5b /* [ */ &&
        res.body[res.body.length - 1] === 0x5d /* ] */
      ) {
        stats.getOk++;
      }
    }
  }
  await Promise.all(Array.from({ length: CONC }, () => worker()));
  return stats;
}

function percentile(sorted, p) {
  if (!sorted.length) return 0;
