  if (finished) return;
  finished = true;
  if (child) { try { child.kill('SIGKILL'); } catch (_) { /* 已退出 */ } }
  emit({
    boot_ok: 0, post_ok: 0, get_ok: 0, round_len_ok: 0, final_field_ok: 0,
